import{_ as i,o as t,c as a,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"ZViewerCLI Local Proxy","description":"","frontmatter":{},"headers":[],"relativePath":"en/cli/index.md","filePath":"en/cli/index.md","lastUpdated":1786689844000}'),n={name:"en/cli/index.md"};function s(r,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="zviewercli-local-proxy" tabindex="-1">ZViewerCLI Local Proxy <a class="header-anchor" href="#zviewercli-local-proxy" aria-label="Permalink to &quot;ZViewerCLI Local Proxy&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>ZViewerCLI is a lightweight proxy program that runs on your local machine, designed to solve the problem that browsers cannot directly use your Bilibili Cookie to obtain high-quality video streams.</p><p>In short: <strong>Install the CLI, and you can watch Bilibili premium member quality videos in ZViewer.</strong></p><hr><h2 id="why-zviewercli-is-needed" tabindex="-1">Why ZViewerCLI is Needed <a class="header-anchor" href="#why-zviewercli-is-needed" aria-label="Permalink to &quot;Why ZViewerCLI is Needed&quot;">​</a></h2><p>When resolving Bilibili videos directly in ZViewer, there are three limitations:</p><ol><li><strong>Cookie Security</strong>: Browsers cannot safely send your Bilibili Cookie to the server (Cookie should stay on your machine)</li><li><strong>CORS and Hotlink Protection</strong>: Bilibili CDN has strict requirements on request headers (Referer, Origin, User-Agent), and direct browser requests are easily blocked</li><li><strong>Quality Restrictions</strong>: The Bilibili Cookie configured on the server may not be a premium member, preventing access to 1080P+ / 4K and other high-quality streams</li></ol><p>ZViewerCLI&#39;s solution: <strong>Cookie stays only on your local machine, video resolution and stream requests are handled locally</strong>, then forwarded to the browser, perfectly bypassing the above limitations.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Local Cookie Resolution</strong>: Uses your own Bilibili Cookie to resolve videos, supporting premium member high quality</li><li><strong>Video Stream Proxy</strong>: Proxies Bilibili CDN video/audio streams, injecting correct request headers to bypass CORS and hotlink protection</li><li><strong>Automatic CDN Switching</strong>: When a single CDN connection fails, automatically tries backup CDN addresses</li><li><strong>WebSocket Room Registration</strong>: Automatically registers with the ZViewer room, enabling automatic discovery and activation by the frontend</li><li><strong>QR Code Login</strong>: Built-in Bilibili QR code login page, no need to manually copy Cookie</li><li><strong>Local Configuration Page</strong>: Automatically opens a browser configuration page on startup, just fill in the backend address, room ID, and Cookie to connect</li><li><strong>Auto-Reconnect on Disconnect</strong>: Uses exponential backoff strategy to automatically reconnect when disconnected from the ZViewer backend</li></ul><hr><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐     WebSocket      ┌─────────────────┐</span></span>
<span class="line"><span>│   ZViewer Backend │  ◄──────────────►  │  ZViewerCLI     │</span></span>
<span class="line"><span>│  (Room State Sync)│                     │  (Your Machine)  │</span></span>
<span class="line"><span>└─────────────────┘                     └────────┬────────┘</span></span>
<span class="line"><span>       ▲                                         │</span></span>
<span class="line"><span>       │ Socket.IO Sync Playback State            │ Local Resolution/Proxy</span></span>
<span class="line"><span>       │                                         ▼</span></span>
<span class="line"><span>┌──────┴──────────┐                    ┌─────────────────┐</span></span>
<span class="line"><span>│   Your Browser   │  ◄─ Local Proxy URL─│  Bilibili CDN   │</span></span>
<span class="line"><span>│  (ZViewer Frontend)│    (Bypasses CORS)  │  (Video/Audio Streams)│</span></span>
<span class="line"><span>└─────────────────┘                    └─────────────────┘</span></span></code></pre></div><p>Core flow:</p><ol><li>You start ZViewerCLI locally, configure the ZViewer backend address, room ID, and Bilibili Cookie</li><li>ZViewerCLI connects to the ZViewer backend via WebSocket and registers its proxy address with the room</li><li>When the frontend detects a CLI proxy available in the room, it preferentially sends Bilibili video resolution requests to the local CLI</li><li>CLI uses your local Cookie to resolve the video and returns proxied video/audio URLs</li><li>The browser requests the local proxy address, and CLI requests the real data from the upstream Bilibili CDN and forwards it to the browser</li></ol><hr><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="step-1-download" tabindex="-1">Step 1: Download <a class="header-anchor" href="#step-1-download" aria-label="Permalink to &quot;Step 1: Download&quot;">​</a></h3><p>Download the version corresponding to your operating system from <a href="https://github.com/Zero-wyc/ZViewerCLI/releases" target="_blank" rel="noreferrer">ZViewerCLI Releases</a>:</p><table tabindex="0"><thead><tr><th>Operating System</th><th>Download File</th></tr></thead><tbody><tr><td>Windows amd64</td><td><code>zviewer-cli-windows-amd64.exe</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>zviewer-cli-darwin-arm64</code></td></tr><tr><td>Linux amd64</td><td><code>zviewer-cli-linux-amd64</code></td></tr><tr><td>Linux arm64</td><td><code>zviewer-cli-linux-arm64</code></td></tr></tbody></table><h3 id="step-2-start" tabindex="-1">Step 2: Start <a class="header-anchor" href="#step-2-start" aria-label="Permalink to &quot;Step 2: Start&quot;">​</a></h3><p><strong>Windows</strong>: Double-click <code>zviewer-cli-windows-amd64.exe</code>, or run in a terminal:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">zviewer-cli-windows-amd64.exe</span></span></code></pre></div><p><strong>macOS / Linux</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zviewer-cli-darwin-arm64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./zviewer-cli-darwin-arm64</span></span></code></pre></div><p>After starting, manually visit <code>http://127.0.0.1:9333</code> to access the configuration page.</p><h3 id="step-3-configure-and-connect" tabindex="-1">Step 3: Configure and Connect <a class="header-anchor" href="#step-3-configure-and-connect" aria-label="Permalink to &quot;Step 3: Configure and Connect&quot;">​</a></h3><p>Fill in the following on the configuration page:</p><ol><li><strong>ZViewer Backend URL</strong>: e.g., <code>http://localhost:3333</code> or <code>https://your-domain.com</code></li><li><strong>Room ID</strong>: The room number you want to join</li><li><strong>Bilibili Cookie</strong>: Can be obtained automatically via QR code login, or pasted manually</li></ol><p>Click the &quot;Connect&quot; button; CLI will verify the Cookie and register with the room.</p><h3 id="step-4-enable-in-the-room" tabindex="-1">Step 4: Enable in the Room <a class="header-anchor" href="#step-4-enable-in-the-room" aria-label="Permalink to &quot;Step 4: Enable in the Room&quot;">​</a></h3><ol><li>Enter the ZViewer room</li><li>When adding a Bilibili video, open &quot;Bilibili Resolution Settings&quot;</li><li>Toggle the <strong>&quot;CLI Local High-Quality Proxy&quot;</strong> switch on</li><li>The player will now load videos through the local CLI, enjoying premium member quality</li></ol><blockquote><p>If no CLI proxy is detected in the room, the switch will appear disabled. Make sure the CLI has successfully connected.</p></blockquote><hr><h2 id="relationship-with-zviewer" tabindex="-1">Relationship with ZViewer <a class="header-anchor" href="#relationship-with-zviewer" aria-label="Permalink to &quot;Relationship with ZViewer&quot;">​</a></h2><p>ZViewerCLI is an <strong>optional companion component</strong> of ZViewer. You can use ZViewer&#39;s basic resolution functionality without installing the CLI.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Without CLI</th><th>With CLI</th></tr></thead><tbody><tr><td>Regular Bilibili videos</td><td>Yes, plays normally</td><td>Yes, plays normally</td></tr><tr><td>Premium member exclusive videos</td><td>No, cannot play</td><td>Yes, can play</td></tr><tr><td>High quality (1080P+/4K)</td><td>Depends on server configuration</td><td>Yes, your personal premium member benefits</td></tr><tr><td>Video stream stability</td><td>Limited by CORS</td><td>Yes, local proxy, stable and reliable</td></tr></tbody></table><p>The main ZViewer project handles room state synchronization, user management, and playback control; ZViewerCLI handles localized Bilibili resolution and stream proxy. The two collaborate via WebSocket and local HTTP API.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>See the <a href="/en/cli/guide">Usage Guide</a> -- command-line arguments, build methods, frequently asked questions</li></ul>`,42)])])}const m=i(n,[["render",s]]);export{u as __pageData,m as default};
